test("history follows scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "perm-void", "clerk");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  await ui.setSetting(pg_uma, "proof-threshold-C", "4.00");
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "7.77");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"})).toBeNull();
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B"})).toBe(true);
  const c_dot_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Dot", "amount": "7.77"}));
  const p_dot = await ui.personId(pg_uma, "Dot");
  await ui.setSetting(pg_uma, "cap", "");
  expect(await ui.periodAction(pg_uma, "2026-04", "soft-close")).toBe(true);
  expect(await ui.movePerson(pg_uma, p_dot, "up")).toBe(true);
  expect(await ui.ratePreview(pg_uma, "B", "7.50")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.claimAction(pg_uma, c_dot_0, "open")).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_dot).getByTestId("person-claimed")).toHaveText("7.77");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
