    }

    /** The sheet's people, in list order. */
    public List<Person> list(String sheetId) {
        return withPatrons(sheetId, jdbc.query(
                "SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? ORDER BY p.list_position, p.id", ROW, sheetId));
    }

    /**
